def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    edge_set = set(edges)

    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edge_set:
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current_sum + weight <= limit:
            current.append(name)
            current_sum += weight
        else:
            batches.append(current)
            current = [name]
            current_sum = weight
    batches.append(current)
    return batches

import re

def parse_env(text):
    result = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()

        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (missing '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    lines = text.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                event_data = '\n'.join(data_lines)
                if event_data == '[DONE]':
                    break
                events.append(event_data)
            data_lines = []
        elif line.startswith(':'):
            continue
        else:
            if ':' in line:
                field, _, value = line.partition(':')
            else:
                field = line
                value = ''
            if field == 'data':
                if value.startswith(' '):
                    value = value[1:]
                data_lines.append(value)

    return events

def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Handles extremely large attempt values (e.g. 10**9) without
    constructing a huge integer or overflowing.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    # Use float exponentiation so that 2.0 ** (10**9) yields inf
    # rather than building a ~300-million-digit integer.
    value = base * (2.0 ** attempt)
    return float(min(cap, value))

def fifo_admit(active, queued, budget, slots):
    for r in queued:
        if r > budget:
            raise ValueError(f"Reservation {r} exceeds budget {budget}")

    avail_budget = budget - sum(active)
    avail_slots = slots - len(active)

    admitted = []
    for r in queued:
        if avail_slots <= 0 or r > avail_budget:
            break
        admitted.append(r)
        avail_budget -= r
        avail_slots -= 1

    split = len(admitted)
    return (list(admitted), list(queued[split:]))
